"""Compute, part A: Kubernetes distributions and managed Kubernetes, orchestrators, virtualization platforms, cloud virtual machines (IaaS),
container runtimes and application platforms (PaaS).

A Kubernetes distribution or a managed Kubernetes follows the generic `kubernetes` kind: the node is the application platform (`workload`,
pods, HPA, `k8s-cluster`), and the description says what the control plane needs. A virtualization platform is a cluster of hosts
(`platform` + `hypervisor`, no `cap`): the virtual machines on it are a `vm_pool`. Provider-run services are `saas` (trait `managed`)."""
from forge import *
from part_b import os_props, runtime_props  # the same OS / runtime lifecycle properties that the generic vm_pool / kubernetes kinds carry

FUNCTIONS = {"compute": [
    ("hypervisor", "Платформы виртуализации", "Virtualization platforms", "server-cog"),
    ("iaas", "Облачные виртуальные машины (IaaS)", "Cloud virtual machines (IaaS)", "cloud-cog"),
    ("container-runtime", "Среды выполнения контейнеров", "Container runtimes", "container"),
    ("paas", "Платформы приложений (PaaS)", "Application platforms (PaaS)", "rocket"),
]}
