K8S_RES = res(1, 2)

# ---- virtualization platforms: a cluster of hosts, `replicas` are the hosts, no `cap` ------------------------------------------------------
C_HV = color_for("compute", "hypervisor")
HV_T = ["platform", "hypervisor"]
HOSTS = ("Хосты", "Hosts")
HV_SUB = ("{replicas}× хостов · {version}", "{replicas}× hosts · {version}")
HV_RES = res(32, 256)

# ---- cloud virtual machines: provider-run (`managed`), the application tier on virtual machines like a vm_pool -----------------------------
VM_SUB = "{replicas}× VM · {vcpu} vCPU"
VM_PROPS = [pr(2, "Виртуальные машины", "Virtual machines")] + res(2, 4, 50) + os_props()

