    # ---- container runtimes ------------------------------------------------------------------------------------------------------------------
    svc("docker_engine", "compute", "container-runtime", "DCK", "Docker Engine", "Docker Engine",
        ("Движок контейнеров на одном хосте: демон dockerd с образами, сетями и томами, Compose запускает на нём несколько контейнеров. Сам по себе он не отказоустойчив — хост остаётся единой точкой отказа, а live-restore лишь сохраняет автономные контейнеры при перезапуске демона; для HA нужны несколько хостов за балансировщиком или Swarm/Kubernetes.",
         "A container engine on a single host: the dockerd daemon with images, networks and volumes, with Compose running several containers on it. It is not fault tolerant by itself — the host stays a single point of failure and live-restore only keeps standalone containers running while the daemon restarts; HA takes several hosts behind a balancer, or Swarm/Kubernetes."),
        table="docker_engine", traits=["workload"] + RT_T, rep=HOSTS, replicas=2, vcpu=4, ram=8, disk=100, cap=150),
    svc("containerd", "compute", "container-runtime", "CTD", "containerd", "containerd",
        ("Среда выполнения контейнеров на каждом узле: стандарт Kubernetes через плагин CRI, её же использует Docker Engine. Это не кластер: отказ узла останавливает его контейнеры, а перезапуск демона запущенные контейнеры не убивает, потому что их держат отдельные shim-процессы.",
         "A container runtime on every node: the Kubernetes standard through its CRI plugin, and the one Docker Engine uses as well. It is not a cluster: a node failure stops its containers, while restarting the daemon does not kill running containers because separate shim processes hold them."),
        versions="", traits=RT_T, rep=NODES, replicas=3, vcpu=4, ram=16, disk=100),
    svc("podman", "compute", "container-runtime", "PDM", "Podman", "Podman",
        ("Движок контейнеров без демона, который работает и от обычного пользователя (rootless): контейнеры и поды — обычные процессы, ими может управлять systemd. Как и Docker, он работает на одном хосте: отказ хоста останавливает его контейнеры, а перезапуск Podman их не затрагивает; для HA нужны несколько хостов за балансировщиком или Kubernetes.",
         "A daemonless container engine that also runs rootless: containers and pods are ordinary processes that systemd can manage. Like Docker it works on a single host: a host failure stops its containers while restarting Podman does not touch them; HA takes several hosts behind a balancer, or Kubernetes."),
        table="podman", traits=["workload"] + RT_T, rep=HOSTS, replicas=2, vcpu=4, ram=8, disk=100, cap=150),
    k("cri_o", "compute", "container-runtime", "CRIO", color_for("compute", "container-runtime"), "CRI-O", "CRI-O", "stateless", RT_T,
      [pv("kubernetes", "Версия CRI-O", "CRI-O version",
          help=("Версия CRI-O совпадает с минорной версией Kubernetes (например, 1.36): срок поддержки проверяется по датам Kubernetes.", "The CRI-O version matches a Kubernetes minor version (for example 1.36): its support dates are those of Kubernetes.")),
       pr(3, *NODES)] + res(4, 16, 100),
      ("Лёгкая среда выполнения контейнеров, реализующая Kubernetes CRI (проект CNCF); запускает OCI-рантаймы, такие как runc и Kata Containers, а версии идут вместе с минорными версиями Kubernetes. Работает на каждом узле: отказ узла останавливает его поды, а обновлять CRI-O нужно по одному узлу вместе с kubelet.",
       "A lightweight container runtime that implements the Kubernetes CRI (a CNCF project) and runs OCI runtimes such as runc and Kata Containers; its versions follow the Kubernetes minor versions. It runs on every node: a node failure stops its pods, and CRI-O is upgraded node by node together with the kubelet."),
      sub="{replicas}× · {version}", versions="kubernetes"),
    svc("kata_containers", "compute", "container-runtime", "KATA", "Kata Containers", "Kata Containers",
        ("Среда выполнения, которая запускает каждый под или контейнер в лёгкой виртуальной машине (QEMU, Cloud Hypervisor, Firecracker) для изоляции на уровне аппаратной виртуализации; подключается к Kubernetes через CRI (containerd) как RuntimeClass. Узлу нужна аппаратная или вложенная виртуализация, а отказ узла уносит все песочницы на нём.",
         "A container runtime that runs each pod or container in a lightweight virtual machine (QEMU, Cloud Hypervisor, Firecracker) for hardware-level isolation; it plugs into Kubernetes through the CRI (containerd) as a RuntimeClass. The node needs hardware or nested virtualization, and a node failure takes all the sandboxes on it down."),
        versions="", traits=RT_T, rep=NODES, replicas=3, vcpu=4, ram=16, disk=100),
    svc("gvisor", "compute", "container-runtime", "GVS", "gVisor", "gVisor",
        ("Песочница для контейнеров: ядро приложений на Go в пользовательском пространстве перехватывает системные вызовы и изолирует контейнер от ядра хоста без полной виртуализации (OCI-рантайм runsc). Совместимость с Linux неполная, а нагрузки с большим числом системных вызовов работают медленнее; отказ узла уносит все песочницы на нём.",
         "A container sandbox: an application kernel written in Go that runs in user space, intercepts system calls and isolates the container from the host kernel without full virtualization (the OCI runtime runsc). Linux compatibility is partial and syscall-heavy workloads run slower; a node failure takes all the sandboxes on it down."),
        versions="", traits=RT_T, rep=NODES, replicas=3, vcpu=4, ram=16, disk=100),

